var _currentRoute = 'dashboard';

function go(id) {
 // Salva rota anterior ANTES de atualizar — necessário para checar se voltamos ao dashboard
 var _prevRoute = _currentRoute;
 document.querySelectorAll('.page').forEach(p => { p.classList.remove('active'); p.style.display='none'; });
 document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
 const el = document.getElementById('page-' + id);
 if (el) {
  el.classList.add('active');
  // Restaurar display correto (flex para páginas especiais, block para as demais)
  el.style.display = el.classList.contains('page-flex') ? 'flex' : 'block';
 }
 const r = routes[id];
 if (r) {
 document.getElementById('bc').innerHTML = r.bc;
 document.querySelectorAll('.nav-item').forEach(n => {
 if (n.getAttribute('onclick') && n.getAttribute('onclick').includes("'" + r.nav + "'")) n.classList.add('active');
 });
 // Atualizar botão contextual da topbar
 const btn = document.getElementById('topbar-action-btn');
 if (r.btn) {
 btn.textContent = r.btn.label;
 btn.style.display = '';
 btn._action = r.btn.fn;
 } else {
 btn.style.display = 'none';
 }
 }
 _currentRoute = id;
 window.scrollTo(0, 0);
 // Recarrega dados do dashboard ao navegar para ele a partir de outra página
 // Motivo: _prevRoute guarda a rota anterior real; sem isso a checagem falha
 // porque _currentRoute já foi atualizado para 'dashboard' antes da condição
 if (id === 'dashboard' && _prevRoute !== 'dashboard') {
  buildGreeting();
  _dashTasksInit();
  _dashLoadNotes();
  _dashRenderInbox();
  if (typeof _dashLoad === 'function' && _dbOk) _dashLoad();
 }
 if (id === 'projetos' && _dbOk) {
  _dbLoadProjetos();
 }
 if (id === 'empresas' && _dbOk) {
  _dbLoadEmpresas();
  _dbLoadContatos();
 }
 if (id === 'instalacoes' && _dbOk) {
  _dbLoadInstalacoes();
 }
 if (id === 'melhorias') {
  if (typeof _pageLoadMelhorias === 'function') _pageLoadMelhorias();
 }
 if (id === 'gestor') {
  if (typeof _gestorLoad === 'function') _gestorLoad();
 }
 if (id === 'exec-dash') {
  if (typeof _execDashLoad === 'function') _execDashLoad();
 }
 if (id === 'admin') {
  if (typeof _adminOnEnter === 'function') _adminOnEnter();
 }
}

function topbarAction() {
 const btn = document.getElementById('topbar-action-btn');
 const fn = btn._action;
 if (fn && window[fn]) window[fn]();
}

/* Stubs para páginas sem modal implementado ainda */
function openNovoPerfil() {
 ['np-cod','np-desc','np-medidas','np-trat','np-obs'].forEach(id => {
 const el = document.getElementById(id); if(el) el.value = '';
 });
 ['np-tipo','np-categ','np-mat','np-status'].forEach(id => {
 const el = document.getElementById(id); if(el) el.selectedIndex = 0;
 });
 document.getElementById('modal-novo-perfil').classList.add('open');
}
function closeNovoPerfil() {
 document.getElementById('modal-novo-perfil').classList.remove('open');
}
function openEditPerfil(cod) {
 // Abre o modal com código pré-preenchido para edição
 openNovoPerfil();
 const codEl = document.getElementById('np-cod');
 if(codEl) { codEl.value = cod; codEl.focus(); }
 document.querySelector('#modal-novo-perfil .modal-title').textContent = 'Editar Perfil — ' + cod;
 document.querySelector('#modal-novo-perfil .btn-primary').textContent = 'Salvar alterações';
}
function submitNovoPerfil() {
 const cod = document.getElementById('np-cod')?.value.trim();
 const desc = document.getElementById('np-desc')?.value.trim();
 const tipo = document.getElementById('np-tipo')?.value;
 const categ = document.getElementById('np-categ')?.value;
 const mat = document.getElementById('np-mat')?.value;
 const med = document.getElementById('np-medidas')?.value.trim();
 const trat = document.getElementById('np-trat')?.value.trim();
 const stat = document.getElementById('np-status')?.value;
 if (!cod || !desc) { alert('Código e descrição são obrigatórios.'); return; }
 const badgeMap = { 'Telhados':'bg','Steel Frame':'bp','Modular':'bb','Solar / FTV':'bb','Misto':'by' };
 const statMap = { 'Portfólio':'bg','Piloto':'by','Em Desenvolvimento':'by' };
 const bc = badgeMap[categ] || 'bm';
 const bs = statMap[stat] || 'bm';
 const tbody = document.getElementById('cat-actl-body');
 if (tbody) {
 const tr = document.createElement('tr');
 tr.setAttribute('data-cat','actl');
 tr.innerHTML = `
 <td style="font-weight:600;color:var(--green)">${cod}</td>
 <td>${desc}</td>
 <td>${med||'—'}</td>
 <td>${mat||'—'}</td>
 <td>${trat||'—'}</td>
 <td><span class="badge ${bc}">${categ||'—'}</span></td>
 <td><span class="badge ${bs}">${stat}</span></td>
 <td><button class="btn btn-ghost btn-sm" onclick="openEditPerfil('${cod}')">Editar</button></td>`;
 tbody.appendChild(tr);
 // Volta para a aba ACTL
 const firstTab = document.querySelector('#cat-tabs .tab');
 if (firstTab) switchCatTab(firstTab, 'cat-actl');
 }
 closeNovoPerfil();
}
function switchCatTab(tabEl, panelId) {
 document.querySelectorAll('#cat-tabs .tab').forEach(t => t.classList.remove('active'));
 tabEl.classList.add('active');
 ['cat-actl','cat-acfv','cat-dren','cat-fix'].forEach(id => {
 const el = document.getElementById(id); if(el) el.style.display = 'none';
 });
 const panel = document.getElementById(panelId);
 if (panel) panel.style.display = '';
}
function filterCatalogo() {
 const q = document.getElementById('cat-search')?.value.toLowerCase() || '';
 document.querySelectorAll('#page-catalogo table tbody tr').forEach(tr => {
 tr.style.display = tr.textContent.toLowerCase().includes(q) ? '' : 'none';
 });
}
