// SUPABASE — integração com banco de dados
// Motivo: dados persistem entre sessões e usuários;
// localStorage era apenas para o protótipo local
// ══════════════════════════════════════════════════════
var _dbOk = false;
var _empresasArr = []; // cache: [{id, nome, cnpj, estado}]
var _contatosArr = []; // cache: [{id, nome_completo, empresa_id, cargo, email, telefone}]
var _obraAtiva   = null; // obra aberta atualmente no painel


// Cache de vínculos atividade → obra/projeto/melhoria (agora vivem em junction tables)
var _avObraMap = null, _avProjMap = null, _avMelhMap = null; // atividade_id -> id (primeiro vínculo)
async function _dbInit() {
 try {
  const { error } = await _sb.from('obras').select('id').limit(1);
  _dbOk = !error;
  if (_dbOk) _loadUsuariosCache(); // dispara em segundo plano, não bloqueia o init
 } catch(e) { _dbOk = false; }
 const dot = document.getElementById('db-dot');
 const lbl = document.getElementById('db-label');
 if (dot) dot.className = _dbOk ? 'ok' : 'err';
 if (lbl) lbl.textContent = _dbOk ? 'Banco conectado' : 'Sem conexão';
 if (_dbOk) {
  // Badges do menu lateral (Empresas/Obras/Projetos/Entregas/Instalações/
  // Melhorias): contagem via RPC única (rpc_sidebar_counts), disparada já,
  // em paralelo com os carregamentos completos abaixo — NÃO espera por
  // eles. Antes, cada badge só ganhava número como efeito colateral de
  // carregar a lista inteira daquela tabela pra memória (ex.: obras.js
  // setava nav-badge-obras só depois de baixar as 1589 obras), e
  // Instalações nem tinha esse efeito colateral no boot — por isso ficava
  // travada em "—" até o usuário abrir a aba manualmente.
  if (typeof _navBadgesLoadInitial === 'function') _navBadgesLoadInitial();
  _dbLoadObras();
  _dbLoadEmpresas();
  _dbLoadContatos();
  _dbLoadEntregas();
  _dbLoadProjetos();
  _dbLoadObrasKanban();
  // Tempo real: essas 5 tabelas carregam uma única vez aqui no boot (não a
  // cada navegação) — sem isso, mudanças feitas por outro usuário ou pelo
  // sync do Airtable só apareceriam depois de recarregar a página inteira.
  if (typeof _rtWatch === 'function') {
   _rtWatch('obras', function(){ _dbLoadObras(); _dbLoadObrasKanban(); });
   _rtWatch('empresas', _dbLoadEmpresas);
   _rtWatch('contatos', _dbLoadContatos);
   _rtWatch('entregas', _dbLoadEntregas);
   _rtWatch('projetos', _dbLoadProjetos);
  }
 }
 // Motivo: _dashLoad() deve ser chamado sempre após _dbInit, independente
 // de _dbOk — quando sem conexão, ela limpa o "Carregando..." e exibe estado vazio.
 if (typeof _dashLoad === 'function') _dashLoad();
 // Exibir FAB do histórico pessoal após autenticação
 if (typeof _histInit === 'function') _histInit();
}

