/* PAINEL DE PERFIL */
function _applyAvatarEverywhere(src) {
 var els = [
  {img:'pp-avatar-img', letter:'pp-avatar-letter'},
  {img:'sb-avatar-img', letter:'sb-avatar-letter'},
  {img:'dash-avatar-img', letter:'dash-avatar-letter'}
 ];
 els.forEach(function(e) {
  var img = document.getElementById(e.img);
  var ltr = document.getElementById(e.letter);
  if (!img) return;
  if (src) { img.src = src; img.style.display = 'block'; if (ltr) ltr.style.display = 'none'; }
  else { img.src = ''; img.style.display = 'none'; if (ltr) ltr.style.display = 'block'; }
 });
 // Mostra o link "Ajustar enquadramento" só quando já existe uma foto
 var adjustBtn = document.getElementById('pp-avatar-adjust-btn');
 if (adjustBtn) adjustBtn.style.display = src ? 'block' : 'none';
}

