function _loadProfileFromDB() {
 if (!_sb || !_currentUser) return;
 _sb.from('usuarios').select('*').eq('id', _currentUser.id).maybeSingle().then(function(r) {
  if (!r.data) return;
  var d = r.data;
  if (d.nome_display) { localStorage.setItem('pp-name', d.nome_display); }
  if (d.cargo) { localStorage.setItem('pp-cargo', d.cargo); }
  if (d.departamento) { localStorage.setItem('pp-dept', d.departamento); }
  if (d.avatar_url) {
   localStorage.setItem('pp-avatar', d.avatar_url);
   // Migrar base64 legado para Storage
   if (d.avatar_url.startsWith('data:')) { _migrateBase64Avatar(d.avatar_url); }
  }
  _refreshProfileUI();
 });
}

function _migrateBase64Avatar(dataUrl) {
 try {
  var parts = dataUrl.match(/^data:([^;]+);base64,(.+)$/);
  if (!parts) return;
  var mime = parts[1];
  var ext = mime.split('/')[1] || 'jpg';
  var byteStr = atob(parts[2]);
  var arr = new Uint8Array(byteStr.length);
  for (var i = 0; i < byteStr.length; i++) arr[i] = byteStr.charCodeAt(i);
  var blob = new Blob([arr], { type: mime });
  var path = 'user-' + _currentUser.id + '/avatar.' + ext;
  _sb.storage.from('avatars').upload(path, blob, { upsert: true, contentType: mime }).then(function(res) {
   if (res.error) return;
   var publicUrl = 'https://pnecdbobhywfjdadylwt.supabase.co/storage/v1/object/public/avatars/' + path;
   _sb.from('usuarios').upsert({ id: _currentUser.id, email: _currentUser.email, avatar_url: publicUrl, updated_at: new Date().toISOString() }, { onConflict: 'id' }).then(function(){});
   localStorage.setItem('pp-avatar', publicUrl);
   _applyAvatarEverywhere(publicUrl);
   if (_currentUser.email) _avatarCache[_currentUser.email] = publicUrl;
  });
 } catch(e) {}
}
