_dashLoadNotes();
_dashRenderInbox();
_dashLoad();

go('dashboard');

/* ── SIDEBAR: TOGGLE E RESIZE ──────────────────────────────────────── */
// Motivo: sidebar ajustável melhora muito usabilidade em telas menores ou
// quando o usuário quer mais espaço de conteúdo. O estado (largura + aberto)
// é salvo em localStorage para persistir entre sessões.

function _sidebarToggle() {
 var sb     = document.getElementById('sidebar');
 var main   = document.querySelector('.main');
 var handle = document.getElementById('sidebar-resize');
 var isCollapsed = sb.classList.contains('collapsed');
 if (isCollapsed) {
  sb.classList.remove('collapsed');
  if (main)   main.classList.remove('sidebar-collapsed');
  if (handle) handle.style.display = '';
  localStorage.setItem('sb-collapsed', '0');
 } else {
  sb.classList.add('collapsed');
  if (main)   main.classList.add('sidebar-collapsed');
  if (handle) handle.style.display = 'none'; // esconde handle quando recolhido
  localStorage.setItem('sb-collapsed', '1');
 }
}

// Restaura largura e estado ao carregar
(function _sidebarRestore() {
 var sb     = document.getElementById('sidebar');
 var main   = document.querySelector('.main');
 var handle = document.getElementById('sidebar-resize');
 var savedW = parseInt(localStorage.getItem('sb-width') || '0', 10);
 if (savedW >= 160 && savedW <= 420) {
  document.documentElement.style.setProperty('--sidebar-w', savedW + 'px');
  if (sb)     sb.style.width = savedW + 'px';
  if (main)   main.style.marginLeft = savedW + 'px';
  if (handle) handle.style.left = savedW + 'px';
 }
 if (localStorage.getItem('sb-collapsed') === '1') {
  if (sb)     sb.classList.add('collapsed');
  if (main)   main.classList.add('sidebar-collapsed');
  if (handle) handle.style.display = 'none';
 }
})();

// Resize por arrastar a borda direita do sidebar
(function _sidebarResizeInit() {
 var handle = document.getElementById('sidebar-resize');
 var sb     = document.getElementById('sidebar');
 var main   = document.querySelector('.main');
 if (!handle || !sb) return;
 var startX, startW;
 handle.addEventListener('mousedown', function(e) {
  e.preventDefault();
  startX = e.clientX;
  startW = sb.getBoundingClientRect().width;
  handle.classList.add('dragging');
  // Desabilita transição durante drag para resposta imediata
  sb.style.transition = 'none';
  if (main) main.style.transition = 'none';
  document.addEventListener('mousemove', onMove);
  document.addEventListener('mouseup',   onUp);
 });
 function onMove(e) {
  var newW = Math.min(420, Math.max(160, startW + (e.clientX - startX)));
  document.documentElement.style.setProperty('--sidebar-w', newW + 'px');
  sb.style.width              = newW + 'px';
  handle.style.left           = newW + 'px'; // move handle junto com o sidebar
  if (main) main.style.marginLeft = newW + 'px';
 }
 function onUp() {
  handle.classList.remove('dragging');
  sb.style.transition   = '';
  if (main) main.style.transition = '';
  var finalW = sb.getBoundingClientRect().width;
  // Sincroniza handle com posição final
  handle.style.left = finalW + 'px';
  localStorage.setItem('sb-width', String(Math.round(finalW)));
  document.removeEventListener('mousemove', onMove);
  document.removeEventListener('mouseup',   onUp);
 }
})();



